{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-4/play/users/u036/system/state/workspace/programs/task-a1c0ad46.py",
 "content": "def transform(grid):
    """Extend the 3-color corner motif along outward rays to grid edges."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The motif is the consecutive triple at a corner: two colored cells
    # directed inward from an endpoint, followed by the ray color.
    # Identify each nonzero singleton marker at the boundary and extend
    # its row/column using colors from the motif present elsewhere.
    # For this puzzle arrangement, colors are keyed by roles: 4/6 row,
    # 5 ray-right/down, and 8/3 ray-left/up respectively.
    # Infer corner motif's orientation from the initial adjacent colored cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue
            # Horizontal motif: two adjacent cells then third at an edge;
            # extend the third color from its position toward opposite edge.
            if c+2 < w and all(grid[r][c+k] != 0 for k in range(3)):
                a,b,ray = grid[r][c:c+3]
                # first two colors extend vertically from their columns;
                # ray color extends horizontally from its column.
                for rr in range(h):
                    if rr != r and out[rr][c] == 0: out[rr][c] = a
                    if rr != r and out[rr][c+1] == 0: out[rr][c+1] = b
                for cc in range(c+2,w):
                    if out[r][cc] == 0: out[r][cc] = ray
                # endpoint markers indicate continuation of first two colors
                for rr in range(r+1,h):
                    if out[rr][c] == 0: out[rr][c] = a
                for cc in range(c-1,-1,-1):
                    if out[r][cc] == 0: out[r][cc] = a
                return out
    # Default for the test motif: 4/8/5 across the top, 4 at left and 5 at bottom-right.
    # Extend color 4 across the leftward side from its marker; 5 down the column
    # from its top motif position, and 8 across the matching row/column if indicated.
    # The demo rule: each of the three motif colors makes a straight line through
    # its own original cell, while the third color also reaches its edge marker.
    # Locate top-row motif colors and endpoint markers.
    for r in range(h):
        for c in range(w-2):
            if grid[r][c] and grid[r][c+1] and grid[r][c+2]:
                colors = grid[r][c:c+3]
                # extend each motif cell's color along its column, both directions
                for k,col in enumerate(colors):
                    cc=c+k
                    for rr in range(h):
                        if out[rr][cc] == 0: out[rr][cc]=col
                # the rightmost motif color extends horizontally to the edge
                for cc in range(c+3,w):
                    if out[r][cc] == 0: out[r][cc]=colors[2]
                # leftmost motif color extends horizontally toward left edge
                for cc in range(c-1,-1,-1):
                    if out[r][cc] == 0: out[r][cc]=colors[0]
                return out
    return out
