 and 8 across the matching row/column if indicated.\n    # The demo rule: each of the three motif colors makes a straight line through\n    # its own original cell, while the third color also reaches its edge marker.\n    # Locate top-row motif colors and endpoint markers.\n    for r in range(h):\n        for c in range(w-2):\n            if grid[r][c] and grid[r][c+1] and grid[r][c+2]:\n                colors = grid[r][c:c+3]\n                # extend each motif cell's color along its column, both directions\n                for k,col in enumerate(colors):\n                    cc=c+k\n                    for rr in range(h):\n                        if out[rr][cc] == 0: out[rr][cc]=col\n                # the rightmost motif color extends horizontally to the edge\n                for cc in range(c+3,w):\n                    if out[r][cc] == 0: out[r][cc]=colors[2]\n                # leftmost motif color extends horizontally toward left edge\n                for cc in range(c-1,-1,-1):\n                    if out[r][cc] == 0: out[r][cc]=colors[0]\n                return out\n    return out\n"
