 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the horizontal three-color motif.
    for r in range(h):
        for c in range(w - 2):
            colors = grid[r][c:c + 3]
            if not all(colors):
                continue
            # Each motif cell sends a vertical ray down. A matching isolated
            # side/bottom marker stops that ray and connects horizontally.
            for k, color in enumerate(colors):
                col = c + k
                stop = h - 1
                marker = None
                for rr in range(r + 1, h):
                    if grid[rr][0] == color:
                        stop, marker = rr, ('left', rr)
                        break
                    if grid[rr][w - 1] == color:
                        stop, marker = rr, ('right', rr)
                        break
                    if grid[rr][col] == color:
                        stop, marker = rr, ('bottom', rr)
                        break
                for rr in range(r + 1, stop + 1):
                    out[rr][col] = color
                if marker:
                    side, rr = marker
                    if side == 'left':
                        for cc in range(col):
                            out[rr][cc] = color
                    elif side == 'right':
                        for cc in range(col + 1, w):
                            out[rr][cc] = color
                    else:
                        # Bottom marker may be off-axis: connect across its row.
                        for cc in range(col + 1, w):
                            out[rr][cc] = color
            return out
    return out
